#!/bin/bash
# Rebuilds ../plantuml.js from a PlantUML source checkout. See README.md in this folder.
# Usage: build.sh <plantuml-checkout>
set -euo pipefail

here=$(cd "$(dirname "$0")" && pwd)
checkout=$(cd "${1:?usage: build.sh <plantuml-checkout>}" && pwd)
out="$here/../plantuml.js"

# The patches are applied to a throwaway worktree of the checkout's HEAD, so the checkout itself is never touched.
stage=$(mktemp -d)
work="$stage/plantuml"
trap 'git -C "$checkout" worktree remove --force "$work" 2>/dev/null || true; rm -rf "$stage"' EXIT
git -C "$checkout" worktree add --detach "$work" HEAD
git -C "$work" apply "$here"/patches/*.patch

# npmPackage stamps the real version into the engine, where generateJavaScript leaves "$version$".
(cd "$work" && ./gradlew :plantuml-mcp-js:npmPackage -Pfast)

cp "$here/worker.js" "$here/package.json" "$here/package-lock.json" "$stage/"
cp "$work/plantuml-mcp-js/build/npm-mcp-js/engine.js" "$stage/engine.js"
cp "$work/src/main/teavm/generated/themes.js" "$stage/themes.js"
cp "$work/src/main/teavm/stdlib/c4.min.js" "$stage/c4.txt"
(cd "$stage" && npm ci --no-audit --no-fund)

commit=$(git -C "$checkout" rev-parse HEAD)
version=$(cd "$stage" && node -e 'import("./engine.js").then(m => console.log(m.version()))')
(cd "$stage" && npx esbuild worker.js --bundle --platform=node --format=esm --minify --loader:.wasm=binary --loader:.txt=text \
  --banner:js="// Generated by extensions/prism/core/vendor/plantuml/build.sh from $version, commit $commit, with patches/*.patch. Do not edit." \
  --outfile="$out")

echo "plantuml.js: $(du -h "$out" | cut -f1), $version, commit $commit"
